package com.acgreader.mobile;
import android.content.res.AssetManager;import android.net.Uri;import android.webkit.*;import org.json.JSONObject;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.regex.*;
final class LocalGateway {
 static final String ORIGIN="https://appassets.androidplatform.net";
 final AssetManager assets;final Set<HttpURLConnection> active=Collections.newSetFromMap(new ConcurrentHashMap<HttpURLConnection,Boolean>());
 LocalGateway(AssetManager a){assets=a;}
 void cancelAll(){for(HttpURLConnection c:active)c.disconnect();active.clear();}
 boolean allowed(URL u,boolean page){String h=u.getHost();return u.getProtocol().equals("https")&&u.getPort()==-1&&u.getUserInfo()==null&&(page?((h.equals("www.acgmhaa.com")||h.equals("acgmhaa.com"))&&u.getPath().matches("/[A-Za-z0-9_]+/[0-9]+(-[0-9]+)?\\.html")):(h.matches("(file[0-9]*|gif)\\.acgnngca\\.com")||h.equals("m.acgnfl.com")));}
 InputStream remote(String value,boolean page)throws Exception{URL url=new URL(value);for(int i=0;i<5;i++){if(!allowed(url,page))throw new IOException("不支持的来源地址");final HttpURLConnection c=(HttpURLConnection)url.openConnection();active.add(c);c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","Mozilla/5.0 AcgReader/1.0.1");c.setRequestProperty("Accept-Encoding","identity");try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");url=new URL(url,location);active.remove(c);c.disconnect();continue;}if(status!=200)throw new IOException("作品源站返回 HTTP "+status+"，请稍后重试");return new FilterInputStream(c.getInputStream()){@Override public void close()throws IOException{try{super.close();}finally{active.remove(c);c.disconnect();}}};}catch(Exception e){active.remove(c);c.disconnect();throw e;}}throw new IOException("源站重定向次数过多");}
 String text(String url,boolean page)throws Exception{try(InputStream in=remote(url,page);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2000000)throw new IOException("页面数据过大");out.write(b,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
 String resource(String value,String source,String master)throws Exception{URL url=new URL(new URL(source),value);if(!allowed(url,false))throw new IOException("不支持的视频分段地址");Uri child=Uri.parse(url.toString());if(url.getPath().endsWith(".m3u8")&&child.getQueryParameter("m")==null){Uri root=Uri.parse(master);Uri.Builder b=child.buildUpon();for(String key:root.getQueryParameterNames())if(child.getQueryParameter(key)==null)b.appendQueryParameter(key,root.getQueryParameter(key));b.appendQueryParameter("from",root.getPath());child=b.build();}return ORIGIN+"/api/hls?"+new Uri.Builder().appendQueryParameter("url",child.toString()).appendQueryParameter("master",master).build().getEncodedQuery();}
 String rewrite(String text,String source,String master)throws Exception{StringBuilder out=new StringBuilder();Pattern uri=Pattern.compile("URI=\"([^\"]+)\"");for(String line:text.split("\\r?\\n")){if(!line.isEmpty()&&!line.startsWith("#"))line=resource(line.trim(),source,master);else{Matcher m=uri.matcher(line);StringBuffer b=new StringBuffer();while(m.find())m.appendReplacement(b,Matcher.quoteReplacement("URI=\""+resource(m.group(1),source,master)+"\""));m.appendTail(b);line=b.toString();}out.append(line).append('\n');}return out.toString();}
 WebResourceResponse bytes(String mime,String value,int status){WebResourceResponse r=new WebResourceResponse(mime,"UTF-8",new ByteArrayInputStream(value.getBytes(StandardCharsets.UTF_8)));r.setStatusCodeAndReasonPhrase(status,status==200?"OK":"Request failed");r.setResponseHeaders(Collections.singletonMap("Cache-Control","no-store"));return r;}
 WebResourceResponse handle(WebResourceRequest request){Uri uri=request.getUrl();if(!uri.toString().startsWith(ORIGIN+"/"))return null;try{String path=uri.getPath();if(!"GET".equals(request.getMethod()))return bytes("application/json","{\"error\":\"Method not allowed\"}",405);if(path.equals("/api/page")){JSONObject body=new JSONObject();body.put("html",text(uri.getQueryParameter("url"),true));return bytes("application/json",body.toString(),200);}if(path.equals("/api/media")||path.equals("/api/hls")){String url=uri.getQueryParameter("url");if(path.equals("/api/hls")&&new URL(url).getPath().endsWith(".m3u8")){String list=text(url,false);if(!list.startsWith("#EXTM3U"))throw new IOException("源站未返回有效的视频列表");String master=uri.getQueryParameter("master");if(master==null)master=url;return bytes("application/vnd.apple.mpegurl",rewrite(list,url,master),200);}return new WebResourceResponse("application/octet-stream",null,remote(url,false));}String name=path.equals("/")?"index.html":path.substring(1);if(!Arrays.asList("index.html","hls.min.js","mux.min.js","web-client.js","mobile.js","favicon.ico").contains(name))return bytes("text/plain","Not found",404);return new WebResourceResponse(name.endsWith(".html")?"text/html":name.endsWith(".js")?"application/javascript":"image/x-icon",name.endsWith(".ico")?null:"UTF-8",assets.open(name));}catch(Exception e){try{JSONObject body=new JSONObject();body.put("error",e.getMessage()==null?"网络请求失败":e.getMessage());return bytes("application/json",body.toString(),400);}catch(Exception ignored){return bytes("text/plain","Request failed",400);}}}
}
